        protected ImageSpaceBinaryOverlay(
            MemoryPair memoryPair,
            BinaryOverlayFactoryPackage package)
            : base(
                memoryPair: memoryPair,
                package: package)
        {
            this.CustomCtor();
        }

        public static IImageSpaceGetter ImageSpaceFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new ImageSpaceBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IImageSpaceGetter ImageSpaceFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return ImageSpaceFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)ImageSpace_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)ImageSpace_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.INAM:
                {
                    _INAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.INAM;
                }
                case RecordTypeInts.YNAM:
                {
                    _YNAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.YNAM;
                }
                case RecordTypeInts.ZNAM:
                {
                    _DropSoundLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.DropSound;
                }
                case RecordTypeInts.TX00:
                {
                    _TX00Location = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.TX00;
                }
                case RecordTypeInts.CNAM:
                {
                    _CNAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.CNAM;
                }
                case RecordTypeInts.DNAM:
                {
                    _DepthOfFieldLocation = new RangeInt32((stream.Position - offset), finalPos - offset);
                    return (int)ImageSpace_FieldIndex.DepthOfField;
                }
                case RecordTypeInts.ENAM:
                {
                    _ENAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.ENAM;
                }
                case RecordTypeInts.FNAM:
                {
                    _FNAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.FNAM;
                }
                case RecordTypeInts.GNAM:
                {
                    _GNAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.GNAM;
                }
                case RecordTypeInts.HNAM:
                {
                    _HNAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.HNAM;
                }
                case RecordTypeInts.TNAM:
                {
                    _TNAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.TNAM;
                }
                case RecordTypeInts.XNAM:
                {
                    _XNAMLocation = (stream.Position - offset);
                    return (int)ImageSpace_FieldIndex.XNAM;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
